CREATE TABLE t1(w INT,x INT,y INT);WITH RECURSIVE c(w,x) AS (VALUES(1,0) UNION ALL SELECT w+1,x+(w IN(1,3,7,15,31,63)) FROM c WHERE w<100) INSERT INTO t1 SELECT w,x,(w+1)*(w+1) FROM c;CREATE TABLE t2(p INT,q INT,r INT,s INT);INSERT INTO t2 SELECT 101-w,x,10202-y,y FROM t1;CREATE INDEX i1w ON t1("w");CREATE INDEX i1xy ON t1(`x`,'y' ASC);CREATE INDEX i2p ON t2(p);CREATE INDEX i2r ON t2(r);CREATE INDEX i2qs ON t2(q,s);